package org.apache.commons.compress.archivers.ar;

import java.io.*;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.ar.ArArchiveInputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ArArchiveInputStream_close_TriageGen0Test {

    @Test
    public void testClose_WhenNotClosed_ShouldCloseInputAndSetClosedTrue() throws IOException {
        // Arrange
        InputStream mockInput = mock(InputStream.class);
        ArArchiveInputStream inputStream = new ArArchiveInputStream(mockInput);

        // Act
        inputStream.close();

        // Assert
        verify(mockInput, times(1)).close();

        // Verify second call does not trigger close again (branch coverage for !closed)
        inputStream.close();
        verify(mockInput, times(1)).close();
    }

    @Test
    public void testClose_WhenInputThrowsIOException_ShouldPropagateException() throws IOException {
        // Arrange
        InputStream mockInput = mock(InputStream.class);
        doThrow(new IOException("Simulated IO error")).when(mockInput).close();
        ArArchiveInputStream inputStream = new ArArchiveInputStream(mockInput);

        // Act & Assert
        try {
            inputStream.close();
            Assert.fail("Expected IOException to be thrown");
        } catch (IOException e) {
            Assert.assertEquals("Simulated IO error", e.getMessage());
        }
    }

    @Test
    public void testClose_WhenAlreadyClosed_ShouldNotCallInputCloseAgain() throws IOException {
        // Arrange
        InputStream mockInput = mock(InputStream.class);
        ArArchiveInputStream inputStream = new ArArchiveInputStream(mockInput);

        // Act
        inputStream.close(); // First close
        inputStream.close(); // Second close (should hit the 'if (!closed)' branch)

        // Assert
        verify(mockInput, times(1)).close();
    }
}
